// Accessibility-tree snapshot walker (WP4). Run in a sheet, returns a compact tree of roles/names/states.
// Node: { role, id?, level?, name?, states?, children? }. Generic wrappers are flattened.
window.dtA11yTree = function () {
  const ROLE = { H1: 'heading', H2: 'heading', H3: 'heading', BUTTON: 'button', NAV: 'navigation', MAIN: 'main', TEXTAREA: 'textbox', SELECT: 'combobox', DETAILS: 'group', SUMMARY: 'button', UL: 'list', OL: 'list', LI: 'listitem', LABEL: 'label', TABLE: 'table' };
  const name = e => e.getAttribute('aria-label') || (e.getAttribute('aria-labelledby') && document.getElementById(e.getAttribute('aria-labelledby'))?.textContent.trim()) || (/^H[1-6]$|^(BUTTON|A|SUMMARY|LABEL)$/.test(e.tagName) ? e.textContent.trim().replace(/\s+/g, ' ').slice(0, 80) : '') || '';
  const role = e => e.getAttribute('role') || (e.tagName === 'A' ? (e.getAttribute('href') ? 'link' : null) : e.tagName === 'INPUT' ? (e.type === 'checkbox' ? 'checkbox' : e.type === 'date' ? 'textbox' : 'textbox') : e.tagName === 'SECTION' ? ((e.getAttribute('aria-label') || e.getAttribute('aria-labelledby')) ? 'region' : 'section') : ROLE[e.tagName] || null);
  const walk = el => { const out = []; for (const ch of el.children) { if (/^(SCRIPT|STYLE|TEMPLATE)$/.test(ch.tagName) || ch.getAttribute('aria-hidden') === 'true') continue; const r = role(ch), st = {}; for (const k of ['aria-pressed', 'aria-selected', 'aria-expanded', 'aria-live', 'aria-disabled', 'disabled', 'aria-describedby']) if (ch.hasAttribute(k)) st[k] = ch.getAttribute(k) === '' ? true : ch.getAttribute(k); const kids = walk(ch); if (r || Object.keys(st).length || ch.id) { const n = { role: r || 'generic' }; if (ch.id) n.id = ch.id; if (/^H[1-6]$/.test(ch.tagName)) n.level = +ch.tagName[1]; const nm = name(ch); if (nm) n.name = nm; if (Object.keys(st).length) n.states = st; if (kids.length) n.children = kids; out.push(n); } else out.push(...kids); } return out; };
  return { sheet: document.title, url: location.pathname.split('/').pop(), captured: new Date().toISOString(), tree: walk(document.body) };
};
